def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Identity_Theft_Reports_by_Type.csv"
    # File contains non-UTF8 characters (e.g., Windows-1252 en-dash). Try cp1252.
    return pd.read_csv(path, encoding="cp1252")

def process(reportType, idTheftClean) -> pd.DataFrame:
    import pandas as pd

    total_reports = float(reportType['numReports'].sum())

    mask = (
        (idTheftClean['theftType'].astype(str).str.strip().str.casefold() == 'bank account')
        & (idTheftClean['theftSubtype'].astype(str).str.strip().str.casefold() == 'new accounts')
    )
    n = idTheftClean.loc[mask, 'numReports'].sum()

    prop = n / total_reports if total_reports else float('nan')

    return pd.DataFrame([
        {
            'bankAccountNewAccountsReports': int(n),
            'allReports': int(total_reports),
            'proportion': round(prop, 4),
        }
    ])
